const ARGS = (typeof args === 'object' && args) ? args : {}
const ROOT = ARGS.root || '/Users/cstokes/Desktop/Maps'   // the repository's folder; pass args.root when it lives elsewhere (a cloud session)
const DIR = 'docs/validation/coherence'
const FABLE_MODEL = ARGS.fableModel || 'opus'
const OPUS_MODEL = ARGS.opusModel || 'opus'
const STANDIN = FABLE_MODEL !== 'fable'
const MAX_LANES = ARGS.maxLanes || 4
const MAX_REPAIR = ARGS.maxRepairRounds || 1
const DATE = ARGS.date || '2026-09-28'
const FFILE = ARGS.fFile || 'docs/AMENDMENTS-2026-09-28f.md'
const SCRATCH = ARGS.scratch || '/private/tmp/claude-502/-Users-cstokes-Desktop-Maps/c0d81c15-f08e-4364-97ca-c6b05aa13811/scratchpad/coherence'   // pass args.scratch elsewhere, e.g. /tmp/maps-scratch/coherence
const NOTE = ARGS.note ? `\n\n${ARGS.note}` : ''   // a continuation note appended to every seat's prompt (a resume on another machine)
const ONLY = ARGS.only || null   // { phase: 'rewrite', units: ['V03', …] }: run only those seats, then return — several such runs side by side give more lanes where the harness allows few per run; the full run then returns their landed work under the RESUME RULE

let liveLanes = 0
const laneQueue = []
const acquireLane = () => new Promise((resolve) => { if (liveLanes < MAX_LANES) { liveLanes++; resolve() } else laneQueue.push(resolve) })
const releaseLane = () => { const next = laneQueue.shift(); if (next) next(); else liveLanes-- }
const limited = async (fn) => { await acquireLane(); try { return await fn() } finally { releaseLane() } }
const standInNote = (label) => `

STAND-IN NOTICE: you run on ${FABLE_MODEL} standing in for the Fable seat ${label} (owner: "focus all work with opus only"). Do the full job to Fable's standard. Put under the title of every report file you write (never inside section files, volume files or repair blocks): > PENDING FABLE REVIEW — written by ${FABLE_MODEL} standing in for the Fable seat ${label}; covered by the whole-design retrovalidation (J84). Add no row to docs/FABLE-REVIEW-QUEUE.md.`
const fableSeat = (prompt, label, phaseName, schema) => limited(() => agent((STANDIN ? prompt + standInNote(label) : prompt) + NOTE, { label, phase: phaseName, schema, agentType: 'general-purpose', model: FABLE_MODEL }))
const opusSeat = (prompt, label, phaseName, schema) => limited(() => agent(prompt + NOTE, { label, phase: phaseName, schema, agentType: 'general-purpose', model: OPUS_MODEL }))

