// ───────── Prompts and seats of the Assemble, Verify, Repair, Adjudicate and Validate phases (defined before any phase runs, so the stage mode can call them) ─────────
const assemblePrompt = (round) => `${GROUND}

LANE coherence/assemble-r${round}. RESUME CHECK FIRST: if docs/lane-events.log has a line containing "coherence/assemble-r${round} LANDED", read ${DIR}/assemble-r${round}.md and return its summary WITHOUT touching any live file. A mechanical seat: python, no hand edits. ${round === 0 ? `First archive (never overwrite an existing archive; cmp identical; chmod a-w; sha256 recorded): docs/ARCHITECTURE.md → docs/archive/ARCHITECTURE-pre-coherence-${DATE}.md, docs/ARCHITECTURE-RATIONALE.md → docs/archive/ARCHITECTURE-RATIONALE-pre-coherence-${DATE}.md, and every docs/volumes/V*.md and docs/volumes/INDEX.md → docs/archive/volumes-pre-coherence-${DATE}/. Then (1) build the new docs/ARCHITECTURE.md from the section files under ${DIR}/new/base/*/ — each placed by its heading line in the order the headings appear in the archived document (every archived top-level heading matched by exactly one file; a heading with no file or a file with no heading: report and STOP without writing); (2) replace each docs/volumes/V*.md by its new text under ${DIR}/new/volumes/ (a volume with no new file: report and STOP); (3) apply the rationale changes the scope editor's report lists (the index rows it adds go into docs/ARCHITECTURE-RATIONALE.md Part A as full entries where the report provides them).` : `Apply every repair block in ${DIR}/repair-r${round}-*.md: blocks for the base use "=== REPLACE <exact heading line> ===" / "=== INSERT AFTER <exact heading line> ===" / "=== APPEND TO SECTION <exact heading line> ===" on docs/ARCHITECTURE.md (reuse docs/validation/amendments-b/apply-blocks.py; read its usage); blocks for a volume start with "=== FILE docs/volumes/<name>.md ===" followed by one of the same block kinds on that file; a double REPLACE of one heading is merged three-way against the archived text with git merge-file (report conflicts and skip the second); a missing heading or a truncated block: skip and report.`} Then (a) references — resolve every reference in the base and the volumes (§x, §x.y, II.n, D-n, J-…, T-…, V0n §x) against the headings and ids that now exist; list broken ones; fix only mechanical ones (renumberings the rewrite reports record); (b) run python3 docs/validation/bench/doc_checks.py --sections "<every top-level heading key of the base>" with the three-copy method (untouched / new / combined against one corpus snapshot; allow file docs/validation/doc-checks-allow.tsv; allow rows pointing at text this pass removed may be dropped with a note), correct mechanical hits, add reviewed allow rows only for false positives, re-run until it exits 0, record the counts; (c) run python3 tools/bundle_architecture.py and --check (the one-file bundle docs/ARCHITECTURE-FULL.md); (d) write ${DIR}/assemble-r${round}.md: sizes before and after per unit, placement, the broken-reference list, doc-check counts, anything not placed.`

// ───────── Verify → Repair ─────────
const VUNITS = [...BASE_PARTS.map((p) => ({ key: p.key, what: `the base part ${p.note} (sections starting with ${JSON.stringify(p.heads)})`, inv: `${DIR}/inventory-${p.key}.json`, rw: `${DIR}/rewrite-${p.key}.md` })), ...VOL_PAIRS.map((vp) => ({ key: vp.key, what: `the volumes ${vp.vols.map((v) => v.file).join(' and ')}`, inv: `${DIR}/inventory-${vp.key}.json`, rw: vp.vols.map((v) => `${DIR}/rewrite-${v.key}.md`).join(' and ') }))]
const verifyPrompt = (u, round, full) => `${GROUND}

LANE coherence/verify-${u.key}-r${round}. You VERIFY ${u.what} after ${round === 0 ? 'the coherence rewrite' : `repair round ${round}`}, against the archives (docs/archive/ARCHITECTURE-pre-coherence-${DATE}.md and docs/archive/volumes-pre-coherence-${DATE}/), ${u.inv}, ${DIR}/canon.json and ${u.rw} (mapping tables)${round > 0 ? ` and ${DIR}/repair-r${round}-*.md` : ''}. Check EVERY inventory id: LOST (stated nowhere it should be, or a reference points at a section that does not state it), CHANGED (a value, rule or meaning differs from the archive without being an f item applied or a canon ruling), F-MISSING (an f item routed here not applied as written), TERM (a retired term survives), CONFLICT (disagrees with another unit's canonical statement), ID (a colliding id not renumbered, or a renumbering that broke a citation), BROKEN-REFERENCE, DEFERRAL-WORDING, WIRING (a wiring gap routed here not closed, or a new orphan, dangling input, one-ended hook or unreached dossier field the rewrite created — rebuild the graph with python3 ${DIR}/wiring.py over the current text's inventory if you need to), COHESION (for scope: the summary, §1, §14, §15, §16 not true of the whole set; for a volume: its build plan disagreeing with INDEX.md or §16), NUANCE-LOST (always a BLOCKER: a case, exception, distinction, constant, band row, fallback, failure rung, provenance, bar, owner rule or behaviour present in the archive and missing or blurred after an elegance ruling or a cut made for the shrink goal — where your unit shrank by more than half, audit every archived subsection against the new text for this before anything else — check every item of each routed ruling's equivalence list against the archive), ELEGANCE (a MINOR: an elegance ruling routed here not applied, or an unruled duplicate mechanism left in the text), EDGE-UNDEFINED and EDGE-UNTESTED (principle (11): an edge case of this unit's mechanisms, from ${DIR}/edges.json or found by you, without a defined outcome and fallback, or without a test — a BLOCKER when the outcome would be a crash, a hang, lost data, a silent wrong result or a whole-map retry, else a MAJOR), NEW-PROBLEM. ${round === 0 ? 'Also check every cross-part note addressed to your unit in the other rewrite reports. Sample nothing.' : full ? 'This is a FULL SWEEP after repairs: check every inventory id of your unit again against the current text (repairs elsewhere can break your unit), and every issue the repairs claimed to fix. Sample nothing.' : 'This round re-checks what the repair touched and the issues it claimed to fix; other ids keep their earlier verdict.'} Write ${DIR}/verify-${u.key}-r${round}.md and return every issue with its owning unit (one of: ${unitNames}) and an exact required change.`
const repairPrompt = (unit, round, issues) => `${GROUND}

LANE coherence/repair-${unit}-r${round}. Fix these issues in unit ${unit}: ${JSON.stringify(issues)}. Read the issue sources (${DIR}/verify-*-r${round - 1}.md), the archives for anything lost, the canon, and the current text of every subsection concerned (whole). Write ${DIR}/repair-r${round}-${unit}.md containing only repair blocks (base units: "=== REPLACE <exact current heading line> ===" / "=== INSERT AFTER …" / "=== APPEND TO SECTION …" then the complete new subsection text; volume units: first a line "=== FILE docs/volumes/<name>.md ===", then the same block kinds for that file; "=== END ===" after each block). Per the owner's instruction ("if we need to fix anything just do it down the line"), fix EVERY issue, minors included (THE BAR IS ZERO); nothing goes to a fix list. If you judge an issue itself wrong — it misreads the text, contradicts an adjudication or an owner rule, or is a preference rather than a defect — do not fix it: write a block "=== RULING REQUEST <issue id> ===" with the reason and the evidence, and the adjudicator rules it INVALID (closed for good) or FIX (fixed in the next round). Do not edit live files yourself.`
// ───────── Agreement between units (owner, 2026-09-28 ~23:10: "make sure the coherence pass covers: Agreement between volumes") ─────────
const ALL_VOL_KEYS = VOLS.map((v) => v.key)
const SEAMS = [
  { key: 'agree-fabric', members: ['model', 'pipeline', 'V01', 'V02', 'V03', 'V11'], what: 'the plot, building, interior and content chain: districts and neighbourhoods, plots and site plans, building composition, floor plans and every content row they read' },
  { key: 'agree-layers', members: ['model', 'pipeline', 'rendering', 'V04', 'V05', 'V07'], what: 'the layers and the variant products: the underground, the sky islands and the village against the base layer, arena, rendering and rung rules' },
  { key: 'agree-time', members: ['determinism', 'V06', 'V01', 'V02', 'V03', 'V04', 'V05', 'V07'], what: 'time and change: epochs, growth, decline, decay and least-disruption mutation against every volume lifecycle row' },
  { key: 'agree-host', members: ['determinism', 'V08', 'V11', 'V10', 'V09'], what: 'the dossier and the host: the port, the derivation rows, custom content, the ladders, withheld information and what players may see' },
  { key: 'agree-tools', members: ['determinism', 'rendering', 'V09', 'V10'], what: 'the tools: edit events, dry runs, undo, the embedding API, the editor screens, the clerk calls and its why-answers' },
  { key: 'agree-proof', members: ['scope', ...ALL_VOL_KEYS], what: 'proof and plan: every test id and bar, calibration, the combined build plan and INDEX.md against every volume tests (section 7) and build plan (section 8)' },
]
const SEAM_UNITS = SEAMS.map((sm) => ({ key: sm.key, seam: sm }))
const EDGE_GROUPS = [
  { key: 'edges-world', members: ['model', 'kernel', 'pipeline', 'rendering', 'V01', 'V02', 'V03', 'V04', 'V05', 'V07'], what: 'the physical world at its limits and where layers meet: extreme sites (all water, all cliff, no water, an island town, the steepest ground, the smallest thorp, the metropolis cap), and every combination of the ground, walls and their barrier closure, harbours and decks, raised ways, retaining walls, buildings and plans, the underground systems and ruins, and the sky islands' },
  { key: 'edges-life', members: ['determinism', 'scope', 'V06', 'V08', 'V09', 'V10', 'V11', 'V12'], what: 'time, the host, the tools and the tables at their limits: growth from hamlet to city and decline to nothing, epochs undone after a save, save, load, undo, redo, regenerate and migrate at every state, an empty, maximal or self-contradicting dossier, a dossier event against a pin or a lock, edits against locks, everything locked and regenerated, the clerk at its limits, every toggle and preset combination, table rows at their range ends' },
]
const EDGE_UNITS = EDGE_GROUPS.map((eg) => ({ key: eg.key, edge: eg }))
const edgePrompt = (eg, round, full) => `${GROUND}

LANE coherence/verify-${eg.key}-r${round}. You CHECK EDGE CASES AND COMBINATIONS (principle (11)) across ${eg.what}. Members: ${eg.members.join(', ')} (base parts by key; V01 to V12 are the files docs/volumes/V*.md). Read ${DIR}/edges.md and edges.json (the canon's edge catalogue and cross-unit combinations for these members), ${DIR}/canon.md, §5's failure ladders in docs/ARCHITECTURE.md, and the CURRENT text of every mechanism the entries name, whole subsections, never samples. For each catalogued edge and combination, and for any the catalogue missed that you find by walking the members' mechanisms at their limits, check that the text gives a defined outcome, a fallback on the failure ladder (never a whole-map retry) and a test that would catch a regression. ${round === 0 ? 'This is the first check after the rewrite.' : full ? 'This is a FULL SWEEP after repairs: check every entry again, since repairs elsewhere can open new edges.' : 'Re-check the entries the repairs touched and the issues they claimed to fix.'} Issue kinds: EDGE-UNDEFINED and EDGE-UNTESTED (a BLOCKER when the outcome would be a crash, a hang, lost data, a silent wrong result or a whole-map retry, else a MAJOR), CATALOGUE-GAP (MAJOR: an edge or combination the catalogue missed, with its verdict). Write ${DIR}/verify-${eg.key}-r${round}.md and return every issue with its owning unit (the member that must define the outcome, one of: ${unitNames}) and an exact required change.`

const ALL_VUNITS = [...VUNITS, ...SEAM_UNITS, ...EDGE_UNITS]
const seamPrompt = (sm, round, full) => `${GROUND}

LANE coherence/verify-${sm.key}-r${round}. You CHECK AGREEMENT BETWEEN UNITS (principle (10)) across ${sm.what}. Members: ${sm.members.join(', ')} (base parts by key; V01 to V12 are the files docs/volumes/V*.md). Read ${DIR}/agreement.md and agreement.json (the canon's matrix for these members: every shared subject, its canonical home and the ruling on each disagreement), ${DIR}/canon.md, every hand-off list the members carry (a volume's Fix list, Integration notes and cross-volume hand-off rows), and the CURRENT text of every shared item in every member, whole subsections, never samples. For each shared item check: the same name, type, unit, value, enumeration, table and columns, stage order and inputs, event meaning, lifecycle rows (create, read, persist, regenerate, undo, migrate), tool and API shape, test id and bar, and build-plan dependency in every member; one canonical home with the others referencing it; every hand-off closed at its destination. Also hunt for shared subjects the matrix missed (the same record, table, rule, term or number used by two members) and judge them too. ${round === 0 ? 'This is the first check after the rewrite.' : full ? 'This is a FULL SWEEP after repairs: check every shared item again, since repairs elsewhere can break agreement.' : 'Re-check the shared items the repairs touched and the issues they claimed to fix.'} Issue kinds: DISAGREE (a BLOCKER when the statements would make the generator behave differently, else a MAJOR), DUPLICATE-HOME (MAJOR: one shared thing defined in two places), HANDOFF-OPEN (MAJOR: a hand-off not closed at its destination), MATRIX-GAP (MAJOR: a shared subject the matrix missed, with its verdict). Write ${DIR}/verify-${sm.key}-r${round}.md and return every issue with its owning unit (the member that must change, one of: ${unitNames}) and an exact required change.`

// ───────── Reconcile until nothing material is left (owner, 2026-09-28: "due multiple reconciliation rounds until there is nothing material left") ─────────
const ZERO_BAR = ARGS.zeroBar !== false   // owner, 2026-09-29: zero findings of any severity
const MATERIAL = (i) => ZERO_BAR ? !!i : (i.severity === 'blocker' || i.severity === 'major')
const CAP = ARGS.maxRounds || 20
const VCAP = ARGS.maxValidatorRounds || 6
const ADJ_SCHEMA = { type: 'object', properties: { file: { type: 'string' }, rulings: { type: 'number' } }, required: ['file', 'rulings'] }
const UNIT_KEYS = UNITS.map((u) => u.key)
const normUnit = (o) => { const t = String(o || '').trim(); if (UNIT_KEYS.includes(t)) return t; const low = t.toLowerCase(); const b = BASE_PARTS.find((p) => low.startsWith(p.key)); if (b) return b.key; const m = t.toUpperCase().match(/V\s*0?(\d{1,2})/); if (m && Number(m[1]) >= 1 && Number(m[1]) <= 12) return `V${String(Number(m[1])).padStart(2, '0')}`; return 'scope' }
const REPAIR_SCHEMA = { type: 'object', properties: { unit: { type: 'string' }, file: { type: 'string' }, blocks: { type: 'number' }, ruling_requests: { type: 'number' } }, required: ['unit', 'file', 'blocks', 'ruling_requests'] }
const verifySeat = (u, round, tag) => opusSeat((u.seam ? seamPrompt(u.seam, round, tag === 's') : u.edge ? edgePrompt(u.edge, round, tag === 's') : verifyPrompt(u, round, tag === 's')).replace(`verify-${u.key}-r${round}.md`, `verify-${u.key}-r${round}${tag}.md`), `coherence/verify-${u.key}-r${round}${tag}`, 'Verify', CHECK_SCHEMA)
function adjudicatePrompt(round, history, work) { return `${GROUND}

LANE coherence/adjudicate-r${round}. The material issue count has not fallen for two rounds (${JSON.stringify(history)}). Read the verify and repair files of the last three rounds (${DIR}/verify-*-r*.md, ${DIR}/repair-r*-*.md), rule EVERY RULING REQUEST in the last round's repair files (INVALID with its reason, closed for good, or FIX with the required change), and find the issues that recur or ping-pong between units (a fix in one unit re-breaking another, two units each claiming a fact, a canon ruling that cannot be satisfied as written), and write BINDING RULINGS to ${DIR}/adjudication-r${round}.md: for each, the single correct text or decision, the unit that states it, what every other unit references, and any canon entry this changes (append it to ${DIR}/canon.md as a dated ruling). The next repair round applies these rulings as written. Current material issues: ${JSON.stringify(work)}.` }
const repairSeat = (o, round, work, rulingsFile) => fableSeat(repairPrompt(o, round, work.filter((i) => i.owner === o)) + (rulingsFile ? ` BINDING RULINGS: apply ${rulingsFile} where it concerns your unit.` : ''), `coherence/repair-${o}-r${round}`, 'Repair', REPAIR_SCHEMA)
const touchedUnits = (owners) => { const touched = new Set(owners); return ALL_VUNITS.filter((u) => touched.has(u.key) || VOL_PAIRS.some((vp) => vp.key === u.key && vp.vols.some((v) => touched.has(v.key))) || (u.seam && u.seam.members.some((m) => touched.has(m))) || (u.edge && u.edge.members.some((m) => touched.has(m)))) }
function validatePrompt(vround, material, rulingsFile) { return `${GROUND}

LANE coherence/validate-v${vround}. You are the FINAL VALIDATOR of the coherence pass (the Fable seat), round ${vround}. Read: the base's one-page summary, §1, §14, §15, §16 whole; the opening sections (0, 1, 1b) and build plan (8) of every volume; docs/volumes/INDEX.md; ${DIR}/canon.md (with any dated rulings); ${DIR}/wiring.md; the latest ${DIR}/verify-*.md and assemble logs; ${DIR}/fix-list.md if it exists${rulingsFile ? `; ${rulingsFile}` : ''}. Judge the SET as one design: (1) single source (spot-check at least forty canon entries across units); (2) one term per concept (grep every retired term: zero); (3) cohesion — the summary and §1 true of the whole, the package layout and build plan covering every volume in one order, INDEX.md agreeing; (4) references and ids clean (run the resolver yourself); (5) the owner's rules intact at their homes; (6) nothing lost; (7) WIRED — every defect in ${DIR}/wiring.md closed or ruled, the dossier trace complete (every field consumed or ignore-listed; every derived fact traced; every change kind reaching its dependents), no new orphan; (8) ZERO OPEN FINDINGS — no fix list anywhere in the set holds an open item (the volumes' Fix lists, docs/volumes/INDEX.md section 7's fix list, ${DIR}/fix-list.md, docs/validation/**/fix-list.md), and every finding the loop raised is FIXED or ruled INVALID; (9) ELEGANCE WITHOUT LOSING NUANCE — the shrink goal reported honestly (words before and after, per unit and total, by source; a shortfall explained by irreducible content is acceptable, a cut of content is not), every canon elegance ruling applied, and for each unification its equivalence list checked against the archive (zero nuance lost is the bar; a blur is a blocker), with the set measurably simpler where it was ruled so (fewer duplicate mechanisms, records and rule shapes); (10) AGREEMENT BETWEEN VOLUMES — every pair in ${DIR}/agreement.json agrees or is ruled and fixed, every hand-off is closed, and the latest seam checks (${DIR}/verify-agree-*.md) are clean; spot-check at least thirty shared subjects across at least ten different pairs yourself in the current text; (11) EVERY EDGE DEFINED — ${DIR}/edges.json holds no UNDEFINED or UNTESTED entry, the latest edge checks (${DIR}/verify-edges-*.md) are clean, and you walk at least twenty edges and ten cross-unit combinations yourself in the current text, each with its outcome, fallback and test. Material issues still open from the loop: ${JSON.stringify(material)}. RETURN every finding you find, of ANY severity (the bar is zero), with its owning unit (one of: ${unitNames}) and an exact required change — a repair round follows and you are called again. ONLY IF YOU FIND NOTHING AT ALL — zero open findings of any severity in the base and in every volume: rewrite the base's banner line under its title to say the whole set passed the coherence, cohesion and wiring pass on ${DATE} (pointing to ${DIR}/SUMMARY.md) and remains pending the Fable retrovalidation; regenerate the bundle (python3 tools/bundle_architecture.py); write ${DIR}/validate.md and ${DIR}/SUMMARY.md in PLAIN LANGUAGE for the owner (who does not code): what the pass did, how many reconciliation rounds it took and what each found, how big the design is now (base, volumes, the bundle) against the shrink goal — words before and after, per unit and in total, and how much each of the four sources removed, what was merged, renamed, reconciled and wired, what was made more elegant and what was deliberately kept apart because it differs, how many places the volumes disagreed with each other or with the base and how each was settled, how many edge cases and cross-volume combinations were catalogued and how many had to be defined, the base changes the volumes asked for that are now in, a table for the base (its six parts) and for each volume: findings raised, fixed, ruled invalid, open — every open count zero, and what comes next (the Fable retrovalidation, the freeze, the first build spec); log the LANDED line and a hand-log entry with python3 tools/progress.py --log "…".` }

if (ONLY) {
  if (ONLY.phase !== 'rewrite' || !Array.isArray(ONLY.units) || !ONLY.units.every((k) => UNITS.some((u) => u.key === k))) return { error: `args.only must be { phase: 'rewrite', units: [${unitNames}] }` }
  phase('Rewrite')
  const sel = UNITS.filter((u) => ONLY.units.includes(u.key)).sort((a, b) => ONLY.units.indexOf(a.key) - ONLY.units.indexOf(b.key))
  const done = (await parallel(sel.map((u) => () => fableSeat(rewritePrompt(u), `coherence/rewrite-${u.key}`, 'Rewrite', REWRITE_SCHEMA)))).filter(Boolean)
  log(`rewrites (only ${ONLY.units.join(', ')}): ${done.length}/${sel.length}`)
  return { only: ONLY.units, landed: done.map((r) => r.key), rewrites: done.map((r) => ({ key: r.key, kb: [Math.round(r.old_kb), Math.round(r.new_kb)], unmapped: r.facts_unmapped, f: (r.f_applied || []).length })) }
}

// ───────── Stage mode: one step of the verify → repair → validate loop, driven from outside by tools/coherence_driver.py (which keeps the loop state on disk and can split a step's seats over runs side by side) ─────────
const STAGE = ARGS.stage || null   // { kind: 'assemble', round } | { kind: 'verify', round, tag: 's'|'t', units } | { kind: 'adjudicate', round, history, work } | { kind: 'repair', round, work, owners, rulingsFile } | { kind: 'validate', vround, material, rulingsFile }
if (STAGE) {
  const S = STAGE
  if (S.kind === 'describe') return { stage: S.kind, units: ALL_VUNITS.map((u) => ({ key: u.key, members: u.seam ? u.seam.members : u.edge ? u.edge.members : (VOL_PAIRS.find((vp) => vp.key === u.key) || { vols: [{ key: u.key }] }).vols.map((v) => v.key) })), unitKeys: UNIT_KEYS, cap: CAP, vcap: VCAP, zeroBar: ZERO_BAR, material: (S.issues || []).map((i) => MATERIAL(i)), owners: (S.owners || []).map(normUnit), touched: touchedUnits(S.touched || []).map((u) => u.key) }   // no agents: the driver's view of the loop's own rules
  if (S.kind === 'assemble') { phase('Assemble'); const a = await opusSeat(assemblePrompt(S.round), `coherence/assemble-r${S.round}`, 'Assemble', ASSEMBLE_SCHEMA); return { stage: S.kind, round: S.round, ok: !!a } }
  if (S.kind === 'verify') {
    const us = (S.units || []).map((k) => ALL_VUNITS.find((u) => u.key === k))
    if (!us.length || us.some((u) => !u)) return { error: `stage verify: units must be among ${ALL_VUNITS.map((u) => u.key).join(', ')}` }
    phase('Verify')
    const checks = await parallel(us.map((u) => () => verifySeat(u, S.round, S.tag)))
    return { stage: S.kind, round: S.round, tag: S.tag, seats: us.map((u, i) => ({ unit: u.key, ok: !!checks[i], issues: checks[i] ? (checks[i].issues || []).length : null })) }
  }
  if (S.kind === 'adjudicate') { phase('Adjudicate'); const a = await fableSeat(adjudicatePrompt(S.round, S.history, S.work), `coherence/adjudicate-r${S.round}`, 'Adjudicate', ADJ_SCHEMA); return { stage: S.kind, round: S.round, ok: !!a } }
  if (S.kind === 'repair') {
    phase('Repair')
    const reps = await parallel(S.owners.map((o) => () => repairSeat(o, S.round, S.work, S.rulingsFile || '')))
    return { stage: S.kind, round: S.round, seats: S.owners.map((o, i) => ({ unit: o, ok: !!reps[i] })) }
  }
  if (S.kind === 'validate') { phase('Validate'); const v = await fableSeat(validatePrompt(S.vround, S.material || [], S.rulingsFile || ''), `coherence/validate-v${S.vround}`, 'Validate', CHECK_SCHEMA); return { stage: S.kind, vround: S.vround, ok: !!v, issues: v ? (v.issues || []).length : null } }
  return { error: `unknown stage kind ${S.kind}` }
}

// ───────── Inventory ─────────
phase('Inventory')
const invBase = BASE_PARTS.map((p) => () => opusSeat(`${GROUND}

LANE coherence/inventory-${p.key}. Your unit: the base part ${p.note} — the top-level sections of docs/ARCHITECTURE.md whose headings start with ${JSON.stringify(p.heads)} (extract with python by heading; a top-level heading that no part's prefixes claim belongs to scope). Read them COMPLETELY. Inventory every normative item: rules, mechanisms, algorithm steps, interfaces and types (by name), numbers and budgets (with units), tests and bars (ids), decisions (ids), and every DEFINED TERM (the concept and every name the text uses for it). Per item: id (${p.key.toUpperCase()}-0001 …), kind, a one-line statement in our own words with its exact values, every place it is stated in your unit, and whether its subject is owned by your unit, another base part, or a volume (name it — the volumes' subjects: neighbourhoods, buildings, interiors, underground, sky, evolution, village, SettlementForge, application, clerk, content, calibration). For every item also record its WIRING: what it reads, depends on or is produced by, and what reads, uses, renders, exports, tests or calls it — each end by inventory id where it is in your unit, or by section and name where it is elsewhere (a volume, another part, the dossier port, a test). Also list internal conflicts and every cross-reference that does not resolve. Write ${DIR}/inventory-${p.key}.json and .md.`, `coherence/inventory-${p.key}`, 'Inventory', INV_SCHEMA))
const invVol = VOL_PAIRS.map((vp) => () => opusSeat(`${GROUND}

LANE coherence/inventory-${vp.key}. Your units: the design volumes ${vp.vols.map((v) => v.file).join(' and ')} (read each COMPLETELY). Inventory every normative item exactly as for a base part (rules, mechanisms, steps, interfaces, numbers with units, tests, decisions, defined terms — id V0x-0001 …, kind, statement with values, where stated, and whether its subject is owned by this volume, the base (name the section it should cite), or another volume), with its WIRING (what it reads or is produced by, and what uses, renders, exports, tests or calls it — by id or by section and name, including the base hooks it plugs into), plus every place the volume RESTATES a base fact instead of citing it, internal conflicts, and cross-references that do not resolve (to the base, to other volumes, to ${FFILE}). Write ${DIR}/inventory-${vp.key}.json and .md.`, `coherence/inventory-${vp.key}`, 'Inventory', INV_SCHEMA))
const inventories = (await parallel([...invBase, ...invVol])).filter(Boolean)
log(`inventories: ${inventories.length}/${BASE_PARTS.length + VOL_PAIRS.length}; facts ${inventories.reduce((n, i) => n + i.facts, 0)}; terms ${inventories.reduce((n, i) => n + i.terms, 0)}; restatements ${inventories.reduce((n, i) => n + i.restatements, 0)}; internal conflicts ${inventories.reduce((n, i) => n + i.internal_conflicts, 0)}; broken references ${inventories.reduce((n, i) => n + i.broken_references, 0)}`)
if (inventories.length < BASE_PARTS.length + VOL_PAIRS.length) { log('an inventory failed — stopping; resume this run to retry it'); return { error: 'inventory incomplete' } }

// ───────── Wiring ─────────
phase('Wiring')
const WIRE_SCHEMA = { type: 'object', properties: { file: { type: 'string' }, nodes: { type: 'number' }, edges: { type: 'number' }, orphans: { type: 'number' }, dangling: { type: 'number' }, one_ended_hooks: { type: 'number' }, dossier_fields: { type: 'number' }, dossier_unreached: { type: 'number' }, gaps_by_unit: { type: 'array', items: { type: 'object', properties: { unit: { type: 'string' }, gaps: { type: 'number' } }, required: ['unit', 'gaps'] } } }, required: ['file', 'nodes', 'edges', 'orphans', 'dangling', 'one_ended_hooks', 'dossier_fields', 'dossier_unreached', 'gaps_by_unit'] }
const wiring = await fableSeat(`${GROUND}

LANE coherence/wiring. You build the WIRING GRAPH of the whole set and trace the dossier end to end. Read every ${DIR}/inventory-*.json (their WIRING fields; query with python) and, for the dossier, research/sf/mapping.md, research/sf/mapping-verify.md (its corrections bind), research/sf/dossier-model.md (the dossier's fields) and the design's dossier sections (§7.7, §11.3, §11.4, §14 and the port items as they stand in the base, and V08). (1) Build ${DIR}/wiring.json — nodes (records and fields, stages, tables, interfaces, packages, edit kinds, tools, tests, hooks, entity kinds, dossier fields, derivation rows, exports) and typed edges (writes, reads, calls, implements, renders, labels, exports, persists, tests, fills-hook, derives-from, ignores) — with a python script you save as ${DIR}/wiring.py so the graph can be rebuilt from the inventories. (2) List every DEFECT in ${DIR}/wiring.md: orphans (produced, never consumed), dangling inputs (consumed, never produced), interfaces with no implementer or no caller, tables no mechanism reads, edit kinds lacking a tool, a lifecycle row or an undo, tools with no event, stages whose outputs nobody reads, packages with no consumer or an undeclared dependency, hooks with one end, tests with no target, failure-prone mechanisms with no test, entity kinds not rendered, labelled, exported or persisted where they should be, and volume pieces that plug into no base hook. (3) THE DOSSIER TRACE: every dossier field (by its path) → consumed by which mechanism, or on the ignore-list; every derived map fact → its dossier inputs and derivation row; every dossier change kind → the path by which it reaches every dependent fact (envelope, fold, mutation, re-derivation, render, export). (4) For each defect: the unit that must fix it (one of: ${unitNames}), and the exact missing link to write (what connects to what, at which home) or, where the piece has no purpose, a proposal to remove it with the reason. Exclude nothing silently: an intentional one-ended piece (for example a staged hook whose other end is a later stage's volume) is recorded as WIRED-BY with the volume and section that holds its other end.`, 'coherence/wiring', 'Wiring', WIRE_SCHEMA)
if (!wiring) { log('wiring failed — stopping; inventories are on disk'); return { error: 'wiring failed' } }
log(`wiring: ${wiring.nodes} nodes, ${wiring.edges} edges; orphans ${wiring.orphans}, dangling ${wiring.dangling}, one-ended hooks ${wiring.one_ended_hooks}; dossier fields ${wiring.dossier_fields}, unreached ${wiring.dossier_unreached}`)

// ───────── Canon ─────────
phase('Canon')
const canon = await fableSeat(`${GROUND}

LANE coherence/canon. You build the CANON of the whole set (the chief architect's seat). Read every ${DIR}/inventory-*.json (query with python) and .md, ${DIR}/wiring.md and wiring.json (the wiring defects and the dossier trace), docs/volumes/INDEX.md, ${FFILE} whole, the J-VI integration decisions recorded in the volumes, docs/validation/consistency/canon.md (the base's earlier home rules), and the volumes pass's integration report and seam reports (docs/volumes/_integrate.md and every seam report it wrote under docs/volumes/). Produce ${DIR}/canon.json and ${DIR}/canon.md: (1) one entry per distinct fact across the set with its CANONICAL HOME (unit and section) and every place it is stated; (2) the GLOSSARY: one term per concept, the retired synonyms and where each occurs; (3) every CONFLICT with both statements, where each is, and the ruling by the precedence in the principles (cite the owner rule, f item or J-VI decision that decides it); (4) the ROUTING of every ${FFILE} item to the base unit that applies it (by its section), and any f item that conflicts with the owner's rules or another f item, ruled; (5) ID HYGIENE: every duplicated test or decision id across the set, with the renumbering (keep the older id where it is cited most); (6) the WIRING GAPS of ${DIR}/wiring.md, each routed to the unit that writes the missing link (or removes the piece, with the ruling); (7) per unit (${unitNames}): the wiring gaps it closes, the facts it must STATE, the facts it must only REFERENCE, the terms to replace, the conflicts it resolves, the f items it applies, and the cohesion checks that land on it (for scope: the summary, §1, §14, §15, §16 against INDEX.md and the volumes' build plans), and the elegance rulings it applies; (8) ELEGANCE (principle (9)): across the whole set, every place where mechanisms, records, tables or rules do the same job, special cases hide a table, a stored value only repeats a derivable one, a volume re-invents a base mechanism, or one kind of rule takes different shapes — each ruled UNIFY (the unified form, its canonical home, the units that change, and the full EQUIVALENCE LIST: every behaviour, case, bar and owner rule of each original and where it lives in the unified form) or KEEP APART (the nuance that separates them); rule only what the equivalence list fully covers; (10) the EDGE CATALOGUE (principle (11)) in ${DIR}/edges.json and ${DIR}/edges.md: for every mechanism of every unit, its edge cases by the principle's list, each with its defined outcome, its failure rung and its test id where the text has them and marked UNDEFINED or UNTESTED where it does not, routed to the unit that owns the mechanism; and the CROSS-UNIT COMBINATIONS (every pair of features from different units that can meet on one map, at their limits), each with its outcome or marked UNDEFINED, routed to the unit that owns the outcome; (11) every OPEN FINDING the volumes pass left — the unresolved findings of its latest seam reports (docs/volumes/critique/seam-*-r*.md, the highest round of each seam), every volume's Fix-list item (section 13), the fix list of docs/volumes/INDEX.md section 7 (the volumes pass's closing list), and every open item of docs/validation/**/fix-list.md — each routed to the unit that closes it; (9) the AGREEMENT MATRIX (principle (10)) in ${DIR}/agreement.json and ${DIR}/agreement.md: for every pair of units that meet (${unitNames}), every subject they share, each statement with its place, the verdict (agree or disagree), the canonical home, and for each disagreement the ruling by the precedence; plus every open hand-off in the volumes, routed to the unit that closes it. Keep fact ids stable.`, 'coherence/canon', 'Canon', CANON_SCHEMA)
if (!canon) { log('canon failed — stopping; inventories are on disk'); return { error: 'canon failed' } }
log(`canon: ${canon.facts} facts, ${canon.multi_stated} stated more than once, ${canon.conflicts} conflicts, ${canon.terms_retired} terms retired, ${canon.f_items_routed} f items routed, ${canon.id_collisions} id collisions, ${canon.elegance_unify} elegance unifications ruled, ${canon.elegance_keep_apart} kept apart for nuance; agreement: ${canon.agreement_pairs} meeting pairs, ${canon.shared_subjects} shared subjects, ${canon.disagreements} disagreements, ${canon.handoffs_open} open hand-offs; edges: ${canon.edge_cases} catalogued, ${canon.edges_undefined} undefined or untested, ${canon.combinations} cross-unit combinations`)

// ───────── Rewrite ─────────
phase('Rewrite')
function rewritePrompt(u) { return u.kind === 'base' ? `${GROUND}

LANE coherence/rewrite-${u.key}. You are the EDITOR of the base part ${u.p.note} (top-level sections starting with ${JSON.stringify(u.p.heads)}). Read completely: your part of docs/ARCHITECTURE.md, ${DIR}/inventory-${u.key}.md/.json, ${DIR}/canon.md/.json (your STATE, REFERENCE, glossary, conflict, f-item, id and cohesion lists), the f items routed to you in ${FFILE} (whole), the headings of the other parts and of every volume (for references), docs/OWNER-INSTRUCTIONS-2026-09-25.md and docs/DEFINITION.md. Write the COMPLETE new text of each of your top-level sections, one file per section, into ${DIR}/new/base/${u.key}/ (NN-slug.md in document order; each file starts with the section's heading line EXACTLY as it is today so the assembler can place it; keep cited subsection numbers, or record every renumbering in your report). Rules: state each fact you own once, with its value; replace restatements with references (to the base part or the volume that owns the fact); apply every routed f item as written (it is a ruled change); close every wiring gap the canon routes to you (write the missing link at its home: the producer, the consumer, the lifecycle row, the tool, the test, the hook end, the dossier consumption or ignore-list entry) or remove the piece where the canon rules it purposeless; bring every shared subject of the canon's AGREEMENT MATRIX that lands on you into agreement (the canonical statement at its home, a reference elsewhere) and close every hand-off routed to you; define every UNDEFINED or UNTESTED edge and combination of the canon's EDGE CATALOGUE routed to you (its outcome, its failure rung, its test); close every open finding the canon routes to you; resolve your conflicts as the canon rules; replace retired terms; renumber colliding ids as the canon says; apply every ELEGANCE ruling routed to you exactly as ruled, keeping every item of its equivalence list at its new home; within your own text prefer the simplest statement that keeps every case, but make no unification the canon did not rule; cut narration and restatement; change nothing else. ${u.key === 'scope' ? 'SCOPE EXTRA: make the one-page summary, §1, §14, §15 and §16 true of the whole set (the volumes placed in the build plan and the package layout, consistent with INDEX.md); keep the one banner line under the title as it is (the validator rewrites it); keep the Judgment-calls index compact (full entries stay in the rationale file) and add its rows for the f items you and the other parts apply as their editors report them in cross-part notes.' : ''} Write ${DIR}/rewrite-${u.key}.md: sizes before and after in words and in KB with the words removed by source (restatement, narration, duplicated mechanisms, verbose prose; principle (9)'s shrink goal), a MAPPING TABLE (every inventory id of your part → its new section, or referenced to where — none missing), the elegance rulings applied with their equivalence lists ticked, the f items applied, conflicts resolved, renumberings, and CROSS-PART NOTES (what another unit must change; do not edit their files).` : `${GROUND}

LANE coherence/rewrite-${u.key}. You are the EDITOR of the design volume ${u.v.file}. Read completely: the volume, its inventory (${DIR}/inventory-vol-*.json/.md that holds ${u.key}), ${DIR}/canon.md/.json (your STATE, REFERENCE, glossary, conflict, id and cohesion lists), the base sections it cites, the f items that concern it in ${FFILE} (the base will contain them after this pass — cite them as base text, never restate them), and docs/volumes/INDEX.md. Write the COMPLETE new text of the volume to ${DIR}/new/volumes/${u.v.file.split('/').pop()} (same title line and section structure, its marker line kept). Rules: state what the volume owns once; replace every restatement of a base or other-volume fact by a reference; bring every shared subject of the canon's AGREEMENT MATRIX that lands on this volume into agreement with the other units it meets and close every hand-off routed to it; define every UNDEFINED or UNTESTED edge and combination of the canon's EDGE CATALOGUE routed to it (its outcome, its failure rung, its test); resolve your conflicts as the canon rules; close every wiring gap the canon routes to you (the volume's pieces plug into named base hooks and are consumed by named mechanisms, renderers, exports and tests); replace retired terms; renumber colliding ids as the canon says; make every reference resolve; cut narration and restatement; CLOSE the volume's Fix list — every item fixed in the text or, where it is wrong, marked for the adjudicator with its reason — and close every open finding the canon routes to this volume; keep the Integration notes; apply every ELEGANCE ruling routed to you exactly as ruled, keeping every item of its equivalence list; make no unification the canon did not rule; write at build depth the part of every g item from 111 onward the canon routes to this volume (new design, not a change of another decision); change no other design decision. Write ${DIR}/rewrite-${u.key}.md: sizes, the MAPPING TABLE (every inventory id of the volume → where it now lives), the elegance rulings applied with their equivalence lists ticked, conflicts resolved, renumberings, CROSS-PART NOTES.` }
const rewrites = (await parallel(UNITS.map((u) => () => fableSeat(rewritePrompt(u), `coherence/rewrite-${u.key}`, 'Rewrite', REWRITE_SCHEMA)))).filter(Boolean)
log(`rewrites: ${rewrites.length}/${UNITS.length}; size ${Math.round(rewrites.reduce((n, r) => n + (r.old_kb || 0), 0))} KB → ${Math.round(rewrites.reduce((n, r) => n + (r.new_kb || 0), 0))} KB; unmapped ${rewrites.reduce((n, r) => n + (r.facts_unmapped || 0), 0)}; f applied ${rewrites.reduce((n, r) => n + (r.f_applied || []).length, 0)}`)
if (rewrites.length < UNITS.length) { log('not every unit was rewritten — stopping before assembly; nothing changed on the live files; resume this run to retry'); return { error: 'rewrite incomplete', done: rewrites.map((r) => r.key) } }

// ───────── Assemble ─────────
phase('Assemble')
let asm = await opusSeat(assemblePrompt(0), 'coherence/assemble-r0', 'Assemble', ASSEMBLE_SCHEMA)
if (!asm) { log(`assembly failed — the archives (if made) are docs/archive/*pre-coherence-${DATE}*`); return { error: 'assembly failed' } }
log(`assembled: ${Math.round(asm.old_kb)} KB → ${Math.round(asm.new_kb)} KB; broken references ${asm.broken_references}; doc-check hits ${asm.doc_check_hits}; unplaced ${(asm.unplaced || []).length}`)

let round = 0
let issues = []
let material = []
let history = []
let rulingsFile = ''
let pending = []            // material issues handed in by the validator
let pendingRequests = 0     // ruling requests the last repair round wrote (the zero bar)
let vround = 0
let fin = null
const verifyAll = async (units, tag) => {
  const checks = (await parallel(units.map((u) => () => verifySeat(u, round, tag)))).filter(Boolean)
  return checks.flatMap((c) => (c.issues || []).filter(Boolean).map((i) => ({ ...i, reported_by: c.key })))
}
const repairRound = async (work) => {
  round++
  work = work.map((i) => ({ ...i, owner: normUnit(i.owner) }))
  if (pendingRequests > 0 || (history.length >= 3 && history[history.length - 1] >= history[history.length - 3])) {
    phase('Adjudicate')
    const adj = await fableSeat(adjudicatePrompt(round, history, work), `coherence/adjudicate-r${round}`, 'Adjudicate', ADJ_SCHEMA)
    if (adj) rulingsFile = adj.file
  }
  phase('Repair')
  const owners = [...new Set(work.map((i) => i.owner))]
  const reps = await parallel(owners.map((o) => () => repairSeat(o, round, work, rulingsFile)))
  pendingRequests = reps.filter(Boolean).reduce((n, r) => n + (r.ruling_requests || 0), 0)
  phase('Assemble')
  asm = await opusSeat(assemblePrompt(round), `coherence/assemble-r${round}`, 'Assemble', ASSEMBLE_SCHEMA) || asm
  return touchedUnits(owners)
}

outer: while (true) {
  // verify → repair until a FULL SWEEP of every unit finds nothing material
  let units = ALL_VUNITS
  let sweep = true
  let work = pending
  pending = []
  if (work.length) { units = await repairRound(work); sweep = false }
  while (true) {
    phase('Verify')
    issues = await verifyAll(units, sweep ? 's' : 't')
    material = issues.filter(MATERIAL)
    history.push(material.length)
    log(`verify round ${round} (${sweep ? 'full sweep' : 'repaired units'}): ${issues.length} issues, ${material.length} material (${['blocker', 'major', 'minor'].map((x) => `${issues.filter((i) => i.severity === x).length} ${x}`).join(', ')})`)
    if (!material.length) {
      if (sweep) break
      units = ALL_VUNITS; sweep = true; continue
    }
    if (round >= CAP) { log(`CAP of ${CAP} repair rounds reached with ${material.length} material issues left — they go to the validator and the owner summary, not silently dropped`); break }
    units = await repairRound([...material, ...issues.filter((i) => !MATERIAL(i))])
    sweep = false
  }
  // the validator judges the set; material findings send the set back into the loop
  phase('Validate')
  fin = await fableSeat(validatePrompt(vround, material, rulingsFile), `coherence/validate-v${vround}`, 'Validate', CHECK_SCHEMA)
  const vmat = ((fin && fin.issues) || []).filter(MATERIAL)
  log(`validator round ${vround}: ${vmat.length} material issues`)
  if (!vmat.length) break outer
  if (vround >= VCAP || round >= CAP) { log(`validator still finds ${vmat.length} material issues at the caps (validator ${VCAP}, repair ${CAP}) — reported for the owner`); material = vmat; break outer }
  vround++
  pending = vmat
}

return { inventories: inventories.length, canon, rewrites: rewrites.map((r) => ({ key: r.key, kb: [Math.round(r.old_kb), Math.round(r.new_kb)], f: (r.f_applied || []).length })), assembled_kb: asm && [Math.round(asm.old_kb), Math.round(asm.new_kb)], repair_rounds: round, material_history: history, validator_rounds: vround + 1, material_left: material.length, minors_left: issues.filter((i) => !MATERIAL(i)).length }
